func (r *Replica) SendBeacon(peerId int32) {
	r.M.Lock()
	defer r.M.Unlock()

	w := r.PeerWriters[peerId]
	if w == nil {
		r.Printf("Connection to %d lost!", peerId)
		return
	}
	w.WriteByte(defs.GENERIC_SMR_BEACON)
	beacon := &defs.Beacon{
		Timestamp: time.Now().UnixNano(),
	}
	beacon.Marshal(w)
	w.Flush()
}

func (r *Replica) ReplyBeacon(beacon *defs.GBeacon) {
	r.M.Lock()
	defer r.M.Unlock()

	w := r.PeerWriters[beacon.Rid]
	if w == nil {
		r.Printf("Connection to %d lost!", beacon.Rid)
		return
	}
	w.WriteByte(defs.GENERIC_SMR_BEACON_REPLY)
	rb := &defs.BeaconReply{
		Timestamp: beacon.Timestamp,
	}
	rb.Marshal(w)
	w.Flush()
}

func (r *Replica) UpdatePreferredPeerOrder(quorum []int32) {
	aux := make([]int32, r.N)
	i := 0

	for _, p := range quorum {
		if p == r.Id {
			continue
		}
		aux[i] = p
		i++
	}

	for _, p := range r.PreferredPeerOrder {
		found := false
		for j := 0; j < i; j++ {
			if aux[j] == p {
				found = true
				break
			}
		}
		if !found {
			aux[i] = p
			i++
		}
	}

	r.M.Lock()
	r.PreferredPeerOrder = aux
	r.M.Unlock()
}

func (r *Replica) ComputeClosestPeers() []float64 {
	npings := 20

	for j := 0; j < npings; j++ {
		for i := int32(0); i < int32(r.N); i++ {
			if i == r.Id {
				continue
			}
			r.M.Lock()
			if r.Alive[i] {
				r.M.Unlock()
				r.SendBeacon(i)
			} else {
				r.Latencies[i] = math.MaxInt64
				r.M.Unlock()
			}
		}
		time.Sleep(500 * time.Millisecond)
	}

	quorum := make([]int32, r.N)

	r.M.Lock()
	for i := int32(0); i < int32(r.N); i++ {
		pos := 0
		for j := int32(0); j < int32(r.N); j++ {
			if (r.Latencies[j] < r.Latencies[i]) ||
				((r.Latencies[j] == r.Latencies[i]) && (j < i)) {
				pos++
			}
		}
		quorum[pos] = int32(i)
	}
	r.M.Unlock()

	if r.Dt == nil {
		r.UpdatePreferredPeerOrder(quorum)
	} else {
		sort.Slice(r.PreferredPeerOrder, func(i, j int) bool {
			di := r.Dt.WaitDurationID(int(r.PreferredPeerOrder[i]))
			dj := r.Dt.WaitDurationID(int(r.PreferredPeerOrder[j]))
			return dj == time.Duration(0) || di < dj
		})
	}

	latencies := make([]float64, r.N-1)

	for i := 0; i < r.N-1; i++ {
		node := r.PreferredPeerOrder[i]
		lat := float64(r.Latencies[node]) / float64(npings*1000000)
		r.Println(node, "->", lat, "ms")
		latencies[i] = lat
	}

	return latencies
}

func (r *Replica) waitForPeerConnections(done chan bool) {
	var b [4]byte
	bs := b[:4]

	port := strings.Split(r.PeerAddrList[r.Id], ":")[1]
	l, err := net.Listen("tcp", "0.0.0.0:"+port)
	if err != nil {
		r.Fatal(r.PeerAddrList[r.Id], err)
	}
	r.Listener = l
	for i := r.Id + 1; i < int32(r.N); i++ {
		conn, err := r.Listener.Accept()
		if err != nil {
			r.Println("Accept error:", err)
			continue
		}
		if _, err := io.ReadFull(conn, bs); err != nil {
			r.Println("Connection establish error:", err)
			continue
		}
		id := int32(binary.LittleEndian.Uint32(bs))
		r.Peers[id] = conn
		r.PeerReaders[id] = bufio.NewReader(conn)
		r.PeerWriters[id] = bufio.NewWriter(conn)
		r.Alive[id] = true
		r.Printf("IN Connected to %d", id)
	}

	done <- true
}

func (r *Replica) replicaListener(rid int, reader *bufio.Reader) {
	var (
		msgType      uint8
		err          error = nil
		gbeacon      defs.Beacon
		gbeaconReply defs.BeaconReply
	)

	for err == nil && !r.Shutdown {
		if msgType, err = reader.ReadByte(); err != nil {
			break
		}

		switch uint8(msgType) {

		case defs.GENERIC_SMR_BEACON:
			if err = gbeacon.Unmarshal(reader); err != nil {
				break
			}
			r.ReplyBeacon(&defs.GBeacon{
				Rid:       int32(rid),
				Timestamp: gbeacon.Timestamp,
			})
			break

		case defs.GENERIC_SMR_BEACON_REPLY:
			if err = gbeaconReply.Unmarshal(reader); err != nil {
				break
			}
			r.M.Lock()
			r.Latencies[rid] += time.Now().UnixNano() - gbeaconReply.Timestamp
			r.M.Unlock()
			now := time.Now().UnixNano()
			r.Ewma[rid] = 0.99*r.Ewma[rid] + 0.01*float64(now-gbeaconReply.Timestamp)
			break

		default:
			p, exists := r.RPC.Get(msgType)
			if exists {
				obj := p.Obj.New()
				if err = obj.Unmarshal(reader); err != nil {
					break
				}
				go func(obj fastrpc.Serializable) {
					time.Sleep(r.Dt.WaitDurationID(rid))
					p.Chan <- obj
				}(obj)
			} else {
				r.Fatal("Error: received unknown message type ", msgType, " from ", rid)
			}
		}
	}

	r.M.Lock()
	r.Alive[rid] = false
	r.M.Unlock()
}

func (r *Replica) clientListener(conn net.Conn) {
	reader := bufio.NewReader(conn)
	writer := bufio.NewWriter(conn)

	var (
		msgType byte
		err     error
	)

	r.M.Lock()
	r.Println("Client up", conn.RemoteAddr(), "(", r.LRead, ")")
	r.M.Unlock()

	addr := strings.Split(conn.RemoteAddr().String(), ":")[0]
	isProxy := r.Config.Proxy.IsProxy(r.Alias, addr)

	mutex := &sync.Mutex{}

	dchan := defs.NewDelayProposeChan(r.Dt.WaitDuration(addr), r.ProposeChan)

	for !r.Shutdown && err == nil {
		if msgType, err = reader.ReadByte(); err != nil {
			break
		}

		switch uint8(msgType) {
		case defs.PROPOSE:
			propose := &defs.Propose{}
			if err = propose.Unmarshal(reader); err != nil {
				break
			}
			r.M.Lock()
			r.ClientWriters[propose.ClientId] = writer
			r.M.Unlock()
			op := propose.Command.Op
			if r.LRead && (op == state.GET || op == state.SCAN) {
				r.ReplyProposeTS(&defs.ProposeReplyTS{
					OK:        defs.TRUE,
					CommandId: propose.CommandId,
					Value:     propose.Command.Execute(r.State),
					Timestamp: propose.Timestamp,
				}, writer, mutex)
			} else {
				dchan.Write(&defs.GPropose{
					Propose: propose,
					Reply:   writer,
					Mutex:   mutex,
					Proxy:   isProxy,
					Addr:    addr,
				})
			}
			break

		case defs.READ:
			// TODO: do something with this
			read := &defs.Read{}
			if err = read.Unmarshal(reader); err != nil {
				break
			}
			break

		case defs.PROPOSE_AND_READ:
			// TODO: do something with this
			pr := &defs.ProposeAndRead{}
			if err = pr.Unmarshal(reader); err != nil {
				break
			}
			break

		case defs.STATS:
			r.M.Lock()
			b, _ := json.Marshal(r.Stats)
			r.M.Unlock()
			writer.Write(b)
			writer.Flush()

		default:
			p, exists := r.RPC.Get(msgType)
			if exists {
				obj := p.Obj.New()
				if err = obj.Unmarshal(reader); err != nil {
					break
				}
				go func(obj fastrpc.Serializable) {
					time.Sleep(r.Dt.WaitDuration(addr))
					p.Chan <- obj
				}(obj)
			} else {
				r.Fatal("Error: received unknown client message ", msgType)
			}
		}
	}

	conn.Close()
	r.Println("Client down", conn.RemoteAddr())
}

func Leader(ballot int32, repNum int) int32 {
	return ballot % int32(repNum)
}

func NextBallotOf(rid, oldBallot int32, repNum int) int32 {
	return (oldBallot/int32(repNum)+1)*int32(repNum) + rid
}

package defs

import (
	"bufio"
	"net"
	"os"
	"strings"
	"time"
)

var LatencyConf = ""

type LatencyTable struct {
	ti map[int]time.Duration
	tn map[string]time.Duration
	d  time.Duration
}

type DelayProposeChan struct {
	delay time.Duration
	pChan chan *GPropose
	lChan chan logCall
}

type bstNode struct {
	p     *GPropose
	left  *bstNode
	right *bstNode
	ready bool
}

type logCall struct {
	action int
	arg    *GPropose
}

const (
	LOG_INSERT = iota
	LOG_HANDLE
)

func (root *bstNode) insert(p *GPropose) *bstNode {
	if root == nil {
		return &bstNode{
			p: p,
		}
	}
	if j := root.p.CommandId; p.CommandId < j {
		root.left = root.left.insert(p)
	} else if p.CommandId > j {
		root.right = root.right.insert(p)
	}

	return root
}

func (root *bstNode) find(i int32) *bstNode {
	if root == nil {
		return nil
	}
	if j := root.p.CommandId; j == i {
		return root
	} else if j < i {
		return root.right.find(i)
	}
	return root.left.find(i)
}

// call `handle` on each continuous element starting from `min`
// returns new root and the id of the last handled proposal
func (root *bstNode) inorderReady(min int32, handle func(*GPropose)) (*bstNode, int32) {
	if root == nil {
		return nil, min
	}

	l, i := root.left.inorderReady(min, handle)

	if l == nil {
		root.left = nil
	}

	if !root.ready || i != root.p.CommandId-1 {
		return root, i
	}
	handle(root.p)
	r, j := root.right.inorderReady(i+1, handle)
	return r, j
}

func NewDelayProposeChan(d time.Duration, c chan *GPropose) *DelayProposeChan {
	if d == time.Duration(0) {
		return &DelayProposeChan{
			delay: d,
			pChan: c,
		}
	}

	dc := &DelayProposeChan{
		delay: d,
		pChan: c,
		lChan: make(chan logCall),
	}

	var (
		log *bstNode
		min int32 = -1
	)

	go func() {
		for {
			a := <-dc.lChan
			switch a.action {
			case LOG_INSERT:
				log = log.insert(a.arg)
			case LOG_HANDLE:
				n := log.find(a.arg.CommandId)
				if n == nil {
					log = log.insert(a.arg)
					n = log.find(a.arg.CommandId)
				}
				n.ready = true
				log, min = log.inorderReady(min, func(p *GPropose) {
					dc.pChan <- p
				})
			}
		}
	}()

	return dc
}

func (c *DelayProposeChan) Write(p *GPropose) {
	if c.delay == time.Duration(0) {
		c.pChan <- p
		return
	}

	c.lChan <- logCall{
		action: LOG_INSERT,
		arg:    p,
	}
	go func() {
		time.Sleep(c.delay)
		c.lChan <- logCall{
			action: LOG_HANDLE,
			arg:    p,
		}
	}()
}

func NewLatencyTable(conf, myAddr string, addrs []string) *LatencyTable {
	if conf == "" {
		return nil
	}
	f, err := os.Open(conf)
	if err != nil {
		return nil
	}
	defer f.Close()

	myAddr = strings.Split(myAddr, ":")[0]

	dt := &LatencyTable{
		d: time.Duration(0),
	}

	s := bufio.NewScanner(f)
	for s.Scan() {
		data := strings.Split(s.Text(), " ")
		if len(data) == 2 {
			if data[0] == "uniform" {
				if d, err := time.ParseDuration(data[1]); err == nil {
					return &LatencyTable{
						d: time.Duration(int64(d) / int64(2)),
					}
				} else {
					return nil
				}
			}
		}
		if len(data) == 3 {
			d, err := time.ParseDuration(data[2])
			if err != nil {
				continue
			}
			d = time.Duration(int64(d) / int64(2))
			addr1, addr2 := data[0], data[1]
			for i := 0; i < 2; i++ {
				if myAddr != addr1 {
					addr1, addr2 = data[1], data[0]
					continue
				}
				if dt.tn == nil {
					dt.tn = make(map[string]time.Duration)
				}
				dt.tn[addr2] = d
				for rid, addr := range addrs {
					if addr2 == strings.Split(addr, ":")[0] {
						if dt.ti == nil {
							dt.ti = make(map[int]time.Duration)
						}
						dt.ti[rid] = d
					}
				}
			}
		}
	}

	return dt
}

func (dt *LatencyTable) WaitDuration(addr string) time.Duration {
	if dt == nil {
		return time.Duration(0)
	}
	d, exists := dt.tn[strings.Split(addr, ":")[0]]
	if exists {
		return d
	}
	return dt.d
}

func (dt *LatencyTable) WaitDurationID(id int) time.Duration {
	if dt == nil {
		return time.Duration(0)
	}
	d, exists := dt.ti[id]
	if exists {
		return d
	}
	return dt.d
}

func IP() string {
	conn, _ := net.Dial("udp", "8.8.8.8:80")
	conn.Close()
	return conn.LocalAddr().(*net.UDPAddr).IP.String()
}

package state

import (
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"io"
	"strconv"
	"sync"

	"github.com/emirpasic/gods/maps/treemap"
)

type Operation uint8

const (
	NONE Operation = iota
	PUT
	GET
	SCAN
)

type Value []byte

func NIL() Value { return Value([]byte{}) }

type Key int64

type Command struct {
	Op Operation
	K  Key
	V  Value
}

type Id int64
type Phase int8

func NOOP() []Command { return []Command{{NONE, 0, NIL()}} }

type State struct {
	mutex *sync.Mutex
	Store *treemap.Map
}

func KeyComparator(a, b interface{}) int {
	aAsserted := a.(Key)
	bAsserted := b.(Key)
	switch {
	case aAsserted > bAsserted:
		return 1
	case aAsserted < bAsserted:
		return -1
	default:
		return 0
	}
}

func concat(slices []Value) Value {
	var totalLen int
	for _, s := range slices {
		totalLen += len(s)
	}
	tmp := make([]byte, totalLen)
	var i int
	for _, s := range slices {
		i += copy(tmp[i:], s)
	}
	return tmp
}

func InitState() *State {
	return &State{new(sync.Mutex), treemap.NewWith(KeyComparator)}
}

func Conflict(gamma *Command, delta *Command) bool {
	key := gamma.K
	lb := delta.K
	ub := delta.K

	if gamma.Op == SCAN && delta.Op == SCAN {
		return false
	}

	if gamma.Op == SCAN {
		key = delta.K
		lb = gamma.K
		ub = gamma.K + Key(binary.LittleEndian.Uint64(gamma.V))
	} else if delta.Op == SCAN {
		ub = delta.K + Key(binary.LittleEndian.Uint64(delta.V))
	}

	if key >= lb && key <= ub {
		if gamma.Op == PUT || delta.Op == PUT {
			return true
		}
	}
	return false
}

func ConflictBatch(batch1 []Command, batch2 []Command) bool {
	for i := 0; i < len(batch1); i++ {
		for j := 0; j < len(batch2); j++ {
			if Conflict(&batch1[i], &batch2[j]) {
				return true
			}
		}
	}
	return false
}

func IsRead(command *Command) bool {
	return command.Op == GET
}

func (c *Command) Execute(st *State) Value {

	st.mutex.Lock()
	defer st.mutex.Unlock()

	switch c.Op {
	case PUT:
		st.Store.Put(c.K, c.V)

	case GET:
		if value, present := st.Store.Get(c.K); present {
			valAsserted := value.(Value)
			return valAsserted
		}

	case SCAN:
		found := make([]Value, 0)
		count := binary.LittleEndian.Uint64(c.V)
		it := st.Store.Select(func(index interface{}, value interface{}) bool {
			keyAsserted := index.(Key)
			return keyAsserted >= c.K && keyAsserted <= c.K+Key(count)
		}).Iterator()
		for it.Next() {
			valAsserted := it.Value().(Value)
			found = append(found, valAsserted)
		}
		ret := concat(found)
		return ret
	}

	return NIL()
}

func (t *Value) String() string {
	if t == nil || len(*t) == 0 {
		return "(void)"
	}
	return hex.EncodeToString(*t)
}

func (t *Key) String() string {
	return strconv.FormatInt(int64(*t), 16)
}

func (t *Command) String() string {
	ret := ""
	if t.Op == PUT {
		ret = "PUT( " + t.K.String() + " , " + t.V.String() + " )"
	} else if t.Op == GET {
		ret = "GET( " + t.K.String() + " )"
	} else if t.Op == SCAN {
		count := binary.LittleEndian.Uint64(t.V)
		ret = "SCAN( " + t.K.String() + " , " + fmt.Sprint(count) + " )"
	} else {
		ret = "UNKNOWN( " + t.V.String() + " , " + t.K.String() + " )"
	}
	return ret
}

func (t *Command) Marshal(w io.Writer) {
	t.Op.Marshal(w)
	t.K.Marshal(w)
	t.V.Marshal(w)
}

func (t *Command) Unmarshal(r io.Reader) error {

	err := t.Op.Unmarshal(r)
	if err != nil {
		return err
	}

	err = t.K.Unmarshal(r)
	if err != nil {
		return err
	}

	err = t.V.Unmarshal(r)
	if err != nil {
		return err
	}

	return nil
}

func (t *Operation) Marshal(w io.Writer) {
	bs := make([]byte, 1)
	bs[0] = byte(*t)
	w.Write(bs)
}

func (t *Operation) Unmarshal(r io.Reader) error {
	bs := make([]byte, 1)
	if _, err := io.ReadFull(r, bs); err != nil {
		return err
	}
	*t = Operation(bs[0])
	return nil
}

func (t *Key) Marshal(w io.Writer) {
	bs := make([]byte, 8)
	binary.LittleEndian.PutUint64(bs, uint64(*t))
	w.Write(bs)
}

func (t *Key) Unmarshal(r io.Reader) error {
	bs := make([]byte, 8)
	if _, err := io.ReadFull(r, bs); err != nil {
		return err
	}
	*t = Key(binary.LittleEndian.Uint64(bs))
	return nil
}

func (t *Value) Marshal(w io.Writer) {
	bs := make([]byte, 4)
	if t == nil {
		binary.LittleEndian.PutUint16(bs, 0)
		w.Write(bs)
	} else {
		binary.LittleEndian.PutUint16(bs, uint16(len(*t)))
		w.Write(bs)
		w.Write(*t)
	}
}

func (t *Value) Unmarshal(r io.Reader) error {
	bs := make([]byte, 4)
	if _, err := io.ReadFull(r, bs); err != nil {
		return err
	}
	len := binary.LittleEndian.Uint16(bs)
	bs = make([]byte, len)
	if _, err := io.ReadFull(r, bs); err != nil {
		return err
	}
	*t = Value(bs)
	return nil
}

